<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();$students=$pdo->query("SELECT id,nama_lengkap,nis,kelas,level FROM students WHERE status='aktif' ORDER BY kelas,nama_lengkap")->fetchAll();$studentId=(string)($_GET['student_id']??($students[0]['id']??''));$selected=null;foreach($students as $row)if($row['id']===$studentId)$selected=$row;$exams=$pdo->query('SELECT m.*,s.nama_lengkap FROM munaqosyah_exams m JOIN students s ON s.id=m.student_id ORDER BY m.tanggal DESC')->fetchAll();$pageTitle='Form Munaqosyah';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Evaluasi Akhir</p><h1 class="page-title">Form Munaqosyah</h1><p class="page-description">Input mengikuti komponen rekap Excel; nilai, jumlah, rata-rata, dan predikat dihitung otomatis.</p></div><a class="btn btn-soft" href="<?= url('guru/reports.php?type=munaqosyah&student_id='.e($studentId)) ?>">Preview / Cetak Rapor Resmi</a></div><section class="grid grid-2"><article class="card"><h2 class="card-title">Input Nilai Ujian</h2><form method="get" class="field" style="margin-bottom:18px"><label>Nama Peserta Didik</label><select class="select" name="student_id" onchange="this.form.submit()"><?php foreach($students as $student):?><option value="<?= e($student['id']) ?>" <?= $student['id']===$studentId?'selected':'' ?>><?= e($student['nama_lengkap'].' · '.$student['kelas'].' · NIS '.$student['nis']) ?></option><?php endforeach;?></select></form><?php if($selected):?><form action="<?= url('api/exams/index.php') ?>" method="post" data-ajax class="form-grid" data-score-group><?= csrf_field() ?><input type="hidden" name="action" value="save_munaqosyah"><input type="hidden" name="student_id" value="<?= e($studentId) ?>"><div class="field"><label>Tanggal Ujian</label><input class="input" type="date" name="tanggal" value="<?= date('Y-m-d') ?>" required></div><div class="field"><label>Juz</label><input class="input" name="juz" value="30" required></div><div class="field full"><label>Periode Rapor</label><input class="input" name="bulan_tahun" value="<?= e(date('F Y')) ?>" required></div><?php foreach(['nilai_kelancaran'=>'Kelancaran','nilai_makhraj'=>'Makhorijul Huruf','nilai_tajwid'=>'Hukum Tajwid','nilai_hafalan'=>'Sambung Ayat'] as $key=>$label):?><div class="field"><label><?= e($label) ?></label><input class="input" type="number" name="<?= $key ?>" min="0" max="100" step="1" value="80" data-score required></div><?php endforeach;?><div class="field full"><label>Rata-rata Otomatis</label><strong style="font-size:34px;color:var(--green-2)" data-average>80.00</strong></div><?php foreach(['akhlaq'=>'Akhlaq','kedisiplinan'=>'Kedisiplinan','kerapihan'=>'Kerapihan'] as $key=>$label):?><div class="field"><label><?= $label ?></label><select class="select" name="<?= $key ?>"><option>A - Sangat Baik</option><option selected>B - Baik</option><option>C - Cukup</option><option>D - Perlu Bimbingan</option></select></div><?php endforeach;?><div class="field full"><label>Catatan Guru</label><textarea class="textarea" name="catatan_guru"></textarea></div><button class="btn btn-primary field full">Simpan Munaqosyah</button></form><?php endif;?></article><article class="card"><h2 class="card-title">Preview Data Munaqosyah</h2><div class="stat green"><small>Nilai Rata-rata Otomatis</small><strong id="munaqosyah-preview">80.00</strong><span>Predikat mengikuti komposisi nilai sekolah</span></div><div class="alert alert-success" style="margin-top:18px">Data tersimpan ke template rapor Munaqosyah resmi, bukan halaman preview sementara.</div><h3>Riwayat Terbaru</h3><div class="compact-list"><?php foreach(array_slice($exams,0,5) as $exam):$payload=json_decode($exam['hasil_ujian'],true)?:[];?><div class="compact-item"><span><strong><?= e($exam['nama_lengkap']) ?></strong><br><small><?= e(format_date_id($exam['tanggal'])) ?></small></span><strong><?= e((string)($payload['nilaiRataRata']??'-')) ?></strong></div><?php endforeach;?></div></article></section><?php require ROOT_PATH.'/includes/footer.php';?>

